import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import { useAuth } from '../context/AuthContext';

export default function Appointments() {
  const [appointments, setAppointments] = useState([]);
  const { auth } = useAuth();
  const navigate = useNavigate();

  const load = () => api.get('/appointments').then(r => setAppointments(r.data));
  useEffect(() => { load(); }, []);

  const cancel = async (id) => {
    await api.patch(`/appointments/${id}/cancel`);
    load();
  };

  const openChat = (appt) => {
    const otherId = auth.user.role === 'patient' ? appt.doctor._id : appt.patient._id;
    const roomId = [auth.user.id, otherId].sort().join('_');
    navigate(`/chat/${roomId}`);
  };

  return (
    <div className="mt-6">
      <h2 className="text-xl font-bold mb-4">Appointments</h2>
      {appointments.length === 0 && <p className="text-gray-400">No appointments yet.</p>}
      <div className="space-y-3">
        {appointments.map(appt => (
          <div key={appt._id} className="border rounded p-4 flex items-center justify-between">
            <div>
              <p className="font-semibold">
                {auth.user.role === 'patient' ? `Dr. ${appt.doctor?.name}` : appt.patient?.name}
              </p>
              <p className="text-sm text-gray-500">{appt.date} at {appt.time}</p>
              <span className={`text-xs px-2 py-0.5 rounded-full ${appt.status === 'booked' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}>
                {appt.status}
              </span>
            </div>
            <div className="flex gap-2">
              <button onClick={() => openChat(appt)} className="btn-outline text-sm">Chat</button>
              {appt.status === 'booked' && (
                <button onClick={() => cancel(appt._id)} className="text-red-500 text-sm underline">Cancel</button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
